CTexture::CTexture(const char* name)
	{
		m_name = "UNNAMED_TEX";
		m_palette = NULL;

		m_texelBitSize = 0;
		m_selectQwc = 0;
		m_pal_offset = 0;
		m_transparent = false;
		m_palettized = false;
		m_is_mip_child = false;
		m_bumpmap = false;
		m_bilinear = false;
		m_transp_1bit = false;
		m_dynamic = false;
		m_context = false;

		m_width = 0;
		m_height = 0;
		m_gsaddr = 0;
		m_palID = 0;

		m_AssetLib = NULL;
		m_htex_count = 0;

		if (m_name && m_name != "UNNAMED_TEX")
		{
			zfree(m_name);
		}

		m_name = "UNNAMED_TEX";

		if (name)
		{
			m_name = zstrdup(name);
		}
	}
